INSERT IGNORE INTO departments (id, name, code, description, established_year, sort_order) VALUES
('d0000000-0000-0000-0000-000000000001', 'Spices & Essential Oils Research Department', 'DEPT-SPICE', 'National excellence center for large cardamom (Korerima), black pepper, ginger, turmeric, and vanilla breeding and agronomy.', 1998, 1),
('d0000000-0000-0000-0000-000000000002', 'Coffee & Beverage Crops Research Department', 'DEPT-COFFEE', 'Dedicated to Arabica coffee genetic improvement, shade canopy management, cup quality profiling, and processing technology.', 2000, 2),
('d0000000-0000-0000-0000-000000000003', 'Crop Protection & Plant Pathology Department', 'DEPT-PROT', 'Focuses on diagnostic identification and integrated management of coffee berry disease, ginger bacterial wilt, and spice insect pests.', 2002, 3),
('d0000000-0000-0000-0000-000000000004', 'Natural Resources & Soil Science Department', 'DEPT-SOIL', 'Soil fertility mapping, organic composting, agroforestry canopy conservation, and sustainable land management.', 2005, 4),
('d0000000-0000-0000-0000-000000000005', 'Agricultural Economics & Farmer Extension', 'DEPT-EXT', 'Technology transfer, farmer field schools, gender-inclusive adoption studies, and agricultural market linkage research.', 2006, 5);
INSERT IGNORE INTO staff (id, user_id, department_id, first_name, last_name, position, email, phone, areas_of_expertise, bio, is_active, is_featured, sort_order) VALUES
('s0000000-0000-0000-0000-000000000001', 'u0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 'Girma', 'Bekele', 'Center Director & Senior Agronomist', 'girma.bekele@tarc.gov.et', '+251 91 123 4567', '["Spice Agronomy","Cropping Systems","Korerima Breeding"]', 'Dr. Girma has over 18 years of experience leading national spice breeding and sustainable agroforestry initiatives in Ethiopia.', TRUE, TRUE, 1),
('s0000000-0000-0000-0000-000000000002', 'u0000000-0000-0000-0000-000000000003', 'd0000000-0000-0000-0000-000000000001', 'Abebe', 'Tadesse', 'Lead Spice Breeder', 'abebe.tadesse@tarc.gov.et', '+251 92 234 5678', '["Black Pepper Selection","Ginger Micropropagation","Essential Oil Extraction"]', 'M.Sc. in Plant Genetics from Jimma University, specializing in clonal selection of Southwest Ethiopian wild cardamom populations.', TRUE, TRUE, 2),
('s0000000-0000-0000-0000-000000000003', 'u0000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000002', 'Tigist', 'Hailu', 'Senior Coffee Quality Specialist', 'tigist.hailu@tarc.gov.et', '+251 93 345 6789', '["Coffee Cup Quality","Fermentation Physiology","CBD Resistance"]', 'Ph.D. in Food Science & Sensory Profiling, coordinating specialty highland coffee evaluation across Sheka and Keffa zones.', TRUE, TRUE, 3),
('s0000000-0000-0000-0000-000000000004', NULL, 'd0000000-0000-0000-0000-000000000003', 'Dawit', 'Mengistu', 'Plant Pathologist', 'dawit.mengistu@tarc.gov.et', '+251 94 567 8901', '["Coffee Berry Disease","Ginger Bacterial Wilt","IPM"]', 'Specializes in integrated disease management for coffee and spice crops in humid tropical environments.', TRUE, FALSE, 4),
('s0000000-0000-0000-0000-000000000005', NULL, 'd0000000-0000-0000-0000-000000000004', 'Fatima', 'Yusuf', 'Soil Scientist', 'fatima.yusuf@tarc.gov.et', '+251 95 678 9012', '["Soil Fertility","Organic Composting","Agroforestry"]', 'Conducts soil health assessments and develops organic nutrient management protocols for spice and coffee production systems.', TRUE, FALSE, 5),
('s0000000-0000-0000-0000-000000000006', NULL, 'd0000000-0000-0000-0000-000000000005', 'Kassahun', 'Alemayehu', 'Agricultural Economist', 'kassahun.alemayehu@tarc.gov.et', '+251 96 789 0123', '["Market Linkages","Gender Analysis","Technology Adoption"]', 'Leads farmer extension programs and evaluates adoption rates of improved spice and coffee technologies across Sheka Zone.', TRUE, FALSE, 6),
('s0000000-0000-0000-0000-000000000007', NULL, 'd0000000-0000-0000-0000-000000000001', 'Hana', 'Girma', 'Junior Researcher', 'hana.girma@tarc.gov.et', '+251 97 890 1234', '["Turmeric Varieties","Post-Harvest Processing"]', 'B.Sc. in Horticulture, supporting spice variety trials and post-harvest quality assessment at TARC.', TRUE, FALSE, 7),
('s0000000-0000-0000-0000-000000000008', NULL, 'd0000000-0000-0000-0000-000000000002', 'Yonas', 'Bekele', 'Coffee Research Associate', 'yonas.bekele@tarc.gov.et', '+251 98 901 2345', '["Coffee Processing","Shade Tree Management"]', 'Supports coffee sensory evaluation and agroforestry shade canopy research at Tepi station.', TRUE, FALSE, 8);
INSERT IGNORE INTO research_programs (id, department_id, lead_staff_id, title, slug, code, description, objectives, status, sort_order) VALUES
('p0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 's0000000-0000-0000-0000-000000000002', 'National Spice Improvement & Quality Enhancement Program', 'national-spice-improvement-program', 'PROG-SPICE-NAT', 'Focused on germplasm collection, high-yield variety release, clean planting material multiplication, and post-harvest drying standards for Korarima, Ginger, and Turmeric.', '["Release 2 high oleoresin turmeric varieties by 2027","Develop bacterial wilt management protocols for ginger","Standardize solar drying methods for Ethiopian Korarima capsules"]', 'ACTIVE', 1),
('p0000000-0000-0000-0000-000000000002', 'd0000000-0000-0000-0000-000000000002', 's0000000-0000-0000-0000-000000000003', 'Southwest Agroforestry & Specialty Coffee Program', 'southwest-agroforestry-specialty-coffee', 'PROG-COFFEE-SW', 'Optimizing shade tree architecture and microclimate regulation to enhance Arabica cup complexity and mitigate climate change stress in Tepi and Sheka.', '["Profile sensory attributes of forest Arabica accessions","Quantify carbon sequestration in shaded coffee production systems"]', 'ACTIVE', 2),
('p0000000-0000-0000-0000-000000000003', 'd0000000-0000-0000-0000-000000000003', 's0000000-0000-0000-0000-000000000004', 'Integrated Crop Protection for Spice & Coffee Systems', 'integrated-crop-protection-spice-coffee', 'PROG-PROT-INT', 'Developing biological control agents, resistant varieties, and IPM packages for major diseases and pests affecting spice and coffee crops.', '["Identify biocontrol agents for coffee berry disease","Develop ginger bacterial wilt resistant lines"]', 'ACTIVE', 3),
('p0000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000004', 's0000000-0000-0000-0000-000000000005', 'Sustainable Soil Health & Agroforestry Program', 'sustainable-soil-health-agroforestry', 'PROG-SOIL-SUS', 'Building soil organic matter, nutrient cycling, and canopy conservation for long-term productivity of spice-coffee agroforestry systems.', '["Map soil fertility across 5 kebeles in Yeki Woreda","Promote organic composting among smallholder farmers"]', 'ACTIVE', 4);
INSERT IGNORE INTO research_projects (id, program_id, department_id, lead_researcher_id, title, slug, code, summary, objectives, start_date, end_date, status, funding_source, budget) VALUES
('pr000000-0000-0000-0000-000000000001', 'p0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 's0000000-0000-0000-0000-000000000002', 'Adaptability and Capsule Yield Performance of Elite Korarima Clones in Sheka', 'adaptability-capsule-yield-korarima-clones-sheka', 'PRJ-KOR-2026-01', 'Multi-location field trials evaluating 8 selected Korarima clones for resistance to root rot and capsule yield under natural forest canopy.', '["Evaluate capsule dry weight per clump across 3 altitude gradients","Determine essential oil content of sun-dried versus shade-dried seeds"]', '2024-01-15 00:00:00', '2026-12-30 00:00:00', 'ONGOING', 'Ethiopian Institute of Agricultural Research (EIAR)', '450000.00'),
('pr000000-0000-0000-0000-000000000002', 'p0000000-0000-0000-0000-000000000002', 'd0000000-0000-0000-0000-000000000002', 's0000000-0000-0000-0000-000000000003', 'Influence of Shade Canopy on Coffee Cup Quality in Tepi', 'shade-canopy-influence-coffee-cup-quality-tepi', 'PRJ-COF-2026-02', 'Investigating bean density, biochemical acidity, and cup scores of Arabica coffee grown under contrasting indigenous shade tree species.', '["Analyze sensory cup scores by certified Q-graders","Measure photosynthetically active radiation under tree canopies"]', '2023-06-01 00:00:00', '2026-05-31 00:00:00', 'ONGOING', 'Bioversity International & EIAR', '620000.00'),
('pr000000-0000-0000-0000-000000000003', 'p0000000-0000-0000-0000-000000000003', 'd0000000-0000-0000-0000-000000000003', 's0000000-0000-0000-0000-000000000004', 'Screening Ginger Germplasm for Bacterial Wilt Resistance', 'screening-ginger-germplasm-bacterial-wilt-resistance', 'PRJ-GIN-2025-03', 'Evaluating 15 ginger accessions for resistance to Ralstonia solanacearum under controlled greenhouse and field conditions.', '["Identify resistant genotypes from Ethiopian and exotic collections","Develop molecular markers for wilt resistance screening"]', '2023-09-01 00:00:00', '2025-12-31 00:00:00', 'ONGOING', 'National Plant Genetic Resources Center', '280000.00'),
('pr000000-0000-0000-0000-000000000004', 'p0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001', 's0000000-0000-0000-0000-000000000007', 'High Oleoresin Turmeric Variety Development for Southwest Ethiopia', 'high-oleoresin-turmeric-variety-development', 'PRJ-TUR-2025-04', 'Breeding and evaluating turmeric selections with elevated curcumin and oleoresin content suitable for industrial processing.', '["Evaluate 10 turmeric selections for curcumin content","Conduct multi-location yield trials across 3 agroecologies"]', '2024-03-01 00:00:00', '2027-02-28 00:00:00', 'ONGOING', 'TARC Internal Fund', '180000.00'),
('pr000000-0000-0000-0000-000000000005', 'p0000000-0000-0000-0000-000000000003', 'd0000000-0000-0000-0000-000000000003', 's0000000-0000-0000-0000-000000000004', 'Biological Control of Coffee Berry Disease Using Native Antagonists', 'biological-control-coffee-berry-disease', 'PRJ-CBD-2024-05', 'Isolating and evaluating native Trichoderma and Bacillus strains for suppression of Colletotrichum kahawae in coffee plantations.', '["Isolate antagonistic microorganisms from coffee rhizosphere","Evaluate efficacy under field conditions in Sheka zone"]', '2022-07-01 00:00:00', '2025-06-30 00:00:00', 'COMPLETED', 'EIAR Competitive Grant', '350000.00'),
('pr000000-0000-0000-0000-000000000006', 'p0000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000004', 's0000000-0000-0000-0000-000000000005', 'Soil Fertility Mapping for Spice-Coffee Agroforestry in Yeki Woreda', 'soil-fertility-mapping-spice-coffee-agroforestry', 'PRJ-SOL-2025-06', 'GPS-referenced soil sampling and nutrient analysis across 5 kebeles to guide site-specific fertilizer recommendations.', '["Collect 200 soil samples across 5 kebeles","Develop nutrient management recommendations for 3 soil types"]', '2024-06-01 00:00:00', '2026-05-31 00:00:00', 'ONGOING', 'Southwest Regional Research Institute', '220000.00');
INSERT IGNORE INTO publications (id, project_id, title, slug, abstract, publication_type, publisher_or_journal, publication_year, doi_url, peer_reviewed, is_featured) VALUES
('pub00000-0000-0000-0000-000000000001', 'pr000000-0000-0000-0000-000000000001', 'Agronomic Characterization and Essential Oil Composition of Ethiopian Korarima Accessions', 'agronomic-characterization-essential-oil-korarima', 'Aframomum corrorima is an indigenous high-value spice in Ethiopia. This study evaluated twelve accessions for yield attributes and essential oil yield. Clones TAR-04 and TAR-07 demonstrated superior dry capsule yield exceeding 1.8 tons/ha with 4.8% essential oil content.', 'JOURNAL_ARTICLE', 'Ethiopian Journal of Agricultural Sciences', 2025, 'https://doi.org/10.1234/ejas.2025.04.12', TRUE, TRUE),
('pub00000-0000-0000-0000-000000000002', 'pr000000-0000-0000-0000-000000000002', 'Technical Guide for Agroforestry Shade Tree Management in Southwest Ethiopian Coffee', 'technical-guide-agroforestry-shade-tree-coffee', 'A practical extension manual outlining pruning regimes and density recommendations for Cordia africana, Millettia ferruginea, and Albizia gummifera in coffee agroforestry.', 'TECHNICAL_MANUAL', 'TARC Technical Bulletin No. 14', 2026, NULL, TRUE, TRUE),
('pub00000-0000-0000-0000-000000000003', 'pr000000-0000-0000-0000-000000000003', 'First Report of Ralstonia solanacearum Causing Bacterial Wilt on Ginger in Southwest Ethiopia', 'first-report-bacterial-wilt-ginger-southwest-ethiopia', 'This study reports the isolation and identification of Ralstonia solanacearum from wilted ginger plants in Sheka Zone, with implications for disease management.', 'JOURNAL_ARTICLE', 'Plant Disease Journal', 2024, 'https://doi.org/10.1094/PDIS-2024-03-0456', TRUE, FALSE),
('pub00000-0000-0000-0000-000000000004', 'pr000000-0000-0000-0000-000000000004', 'Curcumin Content Variation Among Ethiopian Turmeric Landraces', 'curcumin-content-variation-ethiopian-turmeric', 'Analysis of curcumin and oleoresin content in 10 turmeric landraces collected from diverse agroecologies in Southwest Ethiopia.', 'CONFERENCE_PAPER', 'Proceedings of the 18th Ethiopian Agricultural Research Conference', 2025, NULL, FALSE, FALSE),
('pub00000-0000-0000-0000-000000000005', 'pr000000-0000-0000-0000-000000000005', 'Native Trichoderma Strums as Biocontrol Agents Against Coffee Berry Disease', 'native-trichoderma-biocontrol-coffee-berry-disease', 'Evaluation of 12 native Trichoderma isolates from coffee rhizosphere for antagonistic activity against Colletotrichum kahawae in vitro and under field conditions.', 'JOURNAL_ARTICLE', 'Biological Control Journal', 2024, 'https://doi.org/10.1016/j.biocontrol.2024.105234', TRUE, TRUE),
('pub00000-0000-0000-0000-000000000006', 'pr000000-0000-0000-0000-000000000006', 'Soil Nutrient Status of Spice-Coffee Agroforestry Systems in Yeki Woreda', 'soil-nutrient-status-spice-coffee-agroforestry', 'Comprehensive soil analysis across 200 sampling sites revealing nutrient deficiencies and management recommendations for sustainable spice-coffee production.', 'JOURNAL_ARTICLE', 'Ethiopian Journal of Soil Science', 2025, NULL, TRUE, FALSE),
('pub00000-0000-0000-0000-000000000007', NULL, 'Adoption Rates of Improved Spice Technologies Among Smallholder Farmers in Sheka Zone', 'adoption-rates-improved-spice-technologies', 'A cross-sectional survey of 450 households assessing adoption determinants of improved Korarima planting materials and organic pest management practices.', 'JOURNAL_ARTICLE', 'Agricultural Economics Review', 2025, NULL, TRUE, FALSE),
('pub00000-0000-0000-0000-000000000008', NULL, 'Policy Brief: Strengthening Spice Value Chains for Ethiopia Export Growth', 'policy-brief-strengthening-spice-value-chains', 'Recommending policy interventions for quality standards, processing infrastructure, and market linkage to boost Ethiopia spice export earnings.', 'POLICY_BRIEF', 'TARC Policy Series', 2026, NULL, FALSE, TRUE);
