INSERT IGNORE INTO news (id, author_id, title, slug, summary, content, category, is_published, is_featured) VALUES
('n0000000-0000-0000-0000-000000000001', 'u0000000-0000-0000-0000-000000000001', 'TARC Releases High-Yielding Disease-Resistant Black Pepper Variety "Tepi-Pepper-1"', 'tarc-releases-high-yield-black-pepper-variety', 'After six years of participatory varietal selection, "Tepi-Pepper-1" is officially approved for wide distribution.', 'Tepi Agricultural Research Center is proud to announce the formal release of "Tepi-Pepper-1". The variety exhibits strong resistance to Phytophthora foot rot and yields up to 3.2 tons of dried peppercorns per hectare.', 'RESEARCH_NEWS', TRUE, TRUE),
('n0000000-0000-0000-0000-000000000002', 'u0000000-0000-0000-0000-000000000002', 'TARC Hosts Regional Coffee Quality Evaluation Workshop', 'tarc-hosts-regional-coffee-quality-workshop', 'Over 45 coffee quality experts gathered at TARC for a 3-day sensory evaluation workshop.', 'The workshop brought together Q-graders from Southwest Ethiopia to calibrate cupping protocols and evaluate specialty coffee samples from Sheka and Keffa zones.', 'EVENTS', TRUE, FALSE),
('n0000000-0000-0000-0000-000000000003', 'u0000000-0000-0000-0000-000000000001', 'New Ginger Bacterial Wilt Management Guide Released for Farmers', 'new-ginger-bacterial-wilt-guide-released', 'A practical field guide for managing ginger bacterial wilt has been published.', 'This guide provides smallholder farmers with step-by-step protocols for preventing and managing bacterial wilt in ginger, including resistant variety selection and soil health practices.', 'FARMER_ADVISORY', TRUE, TRUE),
('n0000000-0000-0000-0000-000000000004', 'u0000000-0000-0000-0000-000000000003', 'TARC Researchers Present at International Spice Conference in India', 'tarc-researchers-international-spice-conference', 'Two TARC researchers presented findings on Korarima essential oil at the Global Spice Symposium.', 'Dr. Abebe Tadesse and Hana Girma presented their research on Ethiopian Korarima essential oil composition at the Global Spice Symposium in Kochi, India.', 'RESEARCH_NEWS', TRUE, FALSE),
('n0000000-0000-0000-0000-000000000005', 'u0000000-0000-0000-0000-000000000002', 'TARC Celebrates 25 Years of Agricultural Research Excellence', 'tarc-celebrates-25-years-research', 'Tepi Agricultural Research Center marks a quarter century of service to Ethiopian agriculture.', 'Founded in 2001, TARC has released 12 improved crop varieties and trained over 5,000 farmers in sustainable agricultural practices across Southwest Ethiopia.', 'INSTITUTIONAL', TRUE, TRUE),
('n0000000-0000-0000-0000-000000000006', 'u0000000-0000-0000-0000-000000000001', 'Farmer Field School Enrollment Opens for 2026 Season', 'farmer-field-school-enrollment-2026', 'Registration is now open for the 2026 Farmer Field School program targeting 200 smallholders.', 'TARC invites smallholder farmers from Yeki and Sheka woredas to enroll in the 2026 Farmer Field School, covering improved spice and coffee production technologies.', 'FARMER_ADVISORY', TRUE, FALSE);
INSERT IGNORE INTO events (id, title, slug, event_type, description, location, start_time, end_time, is_all_day, is_published) VALUES
('e0000000-0000-0000-0000-000000000001', 'Annual Tepi Spice & Coffee Farmers Field Day 2026', 'annual-tepi-spice-coffee-farmers-field-day-2026', 'FIELD_DAY', 'Live demonstration of Korarima seedling transplanting and organic pest management for 400+ farmers.', 'TARC Main Demonstration Farm, Tepi Station', '2026-10-15 08:30:00', '2026-10-15 16:30:00', FALSE, TRUE),
('e0000000-0000-0000-0000-000000000002', 'Coffee Cup Quality Training Workshop', 'coffee-cup-quality-training-workshop', 'TRAINING_SESSION', 'Hands-on training for development agents on sensory evaluation and cupping protocols for Arabica coffee.', 'TARC Coffee Laboratory', '2026-09-20 09:00:00', '2026-09-22 17:00:00', FALSE, TRUE),
('e0000000-0000-0000-0000-000000000003', 'National Spice Research Conference 2026', 'national-spice-research-conference-2026', 'CONFERENCE', 'Annual gathering of spice researchers from across Ethiopia to present findings and plan collaborative research.', 'Addis Ababa, EIAR Conference Hall', '2026-11-05 08:00:00', '2026-11-07 17:00:00', TRUE, TRUE),
('e0000000-0000-0000-0000-000000000004', 'Soil Health Workshop for Extension Agents', 'soil-health-workshop-extension-agents', 'WORKSHOP', 'Practical training on soil sampling techniques, organic composting, and nutrient management.', 'TARC Training Center', '2026-08-10 09:00:00', '2026-08-11 16:00:00', FALSE, TRUE),
('e0000000-0000-0000-0000-000000000005', 'Ginger Production Seminar', 'ginger-production-seminar', 'SEMINAR', 'Seminar on improved ginger production technologies including variety selection and post-harvest handling.', 'TARC Auditorium', '2026-07-15 14:00:00', '2026-07-15 17:00:00', FALSE, TRUE),
('e0000000-0000-0000-0000-000000000006', 'Post-Harvest Processing Training for Spice Farmers', 'post-harvest-processing-training-spice', 'TRAINING_SESSION', 'Hands-on training on solar drying, grading, and packaging of Korarima and turmeric.', 'TARC Post-Harvest Unit', '2026-06-01 08:00:00', '2026-06-02 16:00:00', FALSE, TRUE);
